public Pet() {                    // default constructor - no parameters
    petName = "No name yet";
    petAge = 0;
    petWeight = 0;
}

public Pet(String initialName) {  // initializes name only
    petName = initialName;
    petAge = 0;
    petWeight = 0;
}

public Pet(String initialName, int initialAge, double initialWeight) { // initializes everything
    petName = initialName;
    petAge = initialAge;
    petWeight = initialWeight;
}
